}

function flowOptions(help) {
  const lines = String(help || "").split(/\r?\n/);
  const index = lines.findIndex((line) => line.trim() === "Options:");
  if (index < 0) return ["-h, --help"];
  return lines.slice(index + 1).map((line) => line.trim()).filter(Boolean);
}

